// Defaults sets the appropriate defaults for AwsRdsDBInstanceProperties
func (val *AwsRdsDBInstanceProperties) Defaults() *AwsRdsDBInstanceProperties {
	if val == nil {
		return nil
	}
	tmp := *val
	if tmp.BackupRetentionPeriod == nil {
		backupRetentionPeriod_ := 1
		tmp.BackupRetentionPeriod = &backupRetentionPeriod_
	}
	if tmp.PromotionTier == nil {
		promotionTier_ := 1
		tmp.PromotionTier = &promotionTier_
	}
	return &tmp
}

